local KTool = CS.Engine.Lib.KTool
local BaseEffect = import('Game.Chapter.NewChapterEffect.BaseEffect')
local NewChapterConstants = import('Game.Chapter.NewChapterConstants')
local base = BaseEffect
local cs_coroutine = require "XLua.cs_coroutine"
local ResourceModule = CS.Engine.Modules.ResourceModule
local Yielders = CS.Engine.Lib.Yielders
local GameObject = CS.UnityEngine.GameObject

local CharacterDissolveEffect = Class('CharacterDissolveEffect',BaseEffect)

function CharacterDissolveEffect:__init()

end

function CharacterDissolveEffect:__delete()

end

function CharacterDissolveEffect:Initialize(parameters)
    base.StartEffect(self, parameters)
end

function CharacterDissolveEffect:StartEffect(object)
    base.StartEffect(self, object)
    local character = object.object.transform:Find(NewChapterConstants.CharacterName)
    if isNull(character) then
        return
    end
    self.co = cs_coroutine.start(function()
        local loader = ResourceModule.LoadBundleAsync(NewChapterConstants.RoleDisappearEffectMat, nil, true)
        while not loader.IsCompleted do
            coroutine.yield(Yielders.EndOfFrame)
        end

        if loader.IsSuccess then
            local mat = GameObject.Instantiate(loader.ResultObject)
            coroutine.yield(Yielders.EndOfFrame)
            local RoleDisappearEffect = KTool.GetOrAddComponent(character.gameObject,typeof(CS.RoleDisappearEffect))
            if not KTool.IsNull(RoleDisappearEffect)  then
                RoleDisappearEffect.DisappearNoise = mat
                RoleDisappearEffect.DiappearNoiseTiling = CS.UnityEngine.Vector2(1,1)
                RoleDisappearEffect.Validate = true
            end
            self.effectMat = mat
            self.loader = loader
        else
            loader:Release()
        end
        self.isFinish = true
        self.co = nil
    end)
end

function CharacterDissolveEffect:IsFinish()
    base.IsFinish(self)
end

function CharacterDissolveEffect:EndEffect(object)
    base.EndEffect(self, object)
end

function CharacterDissolveEffect:RemoveEffect(object)
    base.RemoveEffect(self, object)

    local character = object.object.transform:Find(NewChapterConstants.CharacterName)
    if isNull(character) then
        return
    end

    local RoleDisappearEffect = KTool.GetOrAddComponent(character.gameObject,typeof(CS.RoleDisappearEffect))
    if not KTool.IsNull(RoleDisappearEffect)  then
        RoleDisappearEffect.Validate = false
    end

    KTool.SafeDelete(self.effectMat)
    if self.co ~= nil then
        cs_coroutine.stop(self.co)
    end
    if not isNull(self.loader) then
        self.loader:Release()
    end
end

function CharacterDissolveEffect:OnDestroy()
    self.controller = nil--luabehaviour 中CSharp对象
    self:Delete()
end

return CharacterDissolveEffect